public interface MemberRepositoryCustom {
    List<Member> search(String username, Integer minAge, String teamName);
}


-- 구현을 쓴다

public class MemberRepositoryCustomImpl implements MemberRepositoryCustom {

    private final EntityManager em;

    public MemberRepositoryCustomImpl(EntityManager em) {
        this.em = em;
    }

    @Override
    public List<Member> search(String username, Integer minAge, String teamName) {
        StringBuilder jpql = new StringBuilder(
                "select m from Member m left join m.team t where 1 = 1");
        Map<String, Object> params = new HashMap<>();

        if (username != null) {
            jpql.append(" and m.username = :username");
            params.put("username", username);
        }
        if (minAge != null) {
            jpql.append(" and m.age >= :minAge");
            params.put("minAge", minAge);
        }
        if (teamName != null) {
            jpql.append(" and t.name = :teamName");
            params.put("teamName", teamName);
        }

        TypedQuery<Member> q = em.createQuery(jpql.toString(), Member.class);
        params.forEach(q::setParameter);
        return q.getResultList();
    }
}

