public interface MemberRepositoryCustom {
    Page<Member> searchPage(String username, Pageable pageable);
}

@Override
public Page<Member> searchPage(String username, Pageable pageable) {
    String base = "from Member m where 1 = 1"
            + (username != null ? " and m.username = :username" : "");

    TypedQuery<Member> rows = em.createQuery("select m " + base, Member.class);
    TypedQuery<Long> count = em.createQuery("select count(m) " + base, Long.class);
    if (username != null) {
        rows.setParameter("username", username);
        count.setParameter("username", username);
    }
    rows.setFirstResult((int) pageable.getOffset());
    rows.setMaxResults(pageable.getPageSize());

    return new PageImpl<>(rows.getResultList(), pageable,
            count.getSingleResult());
}

